package gadomancymodern.client;

import gadomancymodern.Gadomancy;
import net.minecraft.client.gui.screens.MenuScreens;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.event.lifecycle.FMLClientSetupEvent;
import net.minecraftforge.client.event.EntityRenderersEvent;

@Mod.EventBusSubscriber(modid=Gadomancy.MOD_ID,bus=Mod.EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)
public class GadomancyClient {
    @SubscribeEvent public static void setup(FMLClientSetupEvent event){event.enqueueWork(()->{DynamicResearchIcons.setup();
        gadomancymodern.compressor.EssentiaCompressorEntity.CLIENT_EFFECTS=CompressorEffects::tick;gadomancymodern.compressor.DarknessElementEntity.CLIENT_EFFECTS=CompressorEffects::darkness;gadomancymodern.aura.AuraPylonEntity.CLIENT_EFFECTS=AuraPylonEffects::tick;thaumcraft.api.client.ResearchPageRenderers.register(net.minecraft.resources.ResourceLocation.parse("gadomancy:aura_effect_list"),AuraEffectPage::new);gadomancymodern.disguise.DisguiseNetwork.CLIENT_BUBBLES=DisguiseBubbles::emit;net.minecraft.client.renderer.item.ItemProperties.register(Gadomancy.SILVERWOOD_GOLEM.get(),net.minecraft.resources.ResourceLocation.parse("gadomancy:golem_configuration"),(stack,level,entity,seed)->stack.hasTag()?(stack.getTag().contains("advanced")?1:0)+(stack.getTag().contains("core")?2:0):0);
        thaumcraft.api.client.ResearchPageRenderers.register(net.minecraft.resources.ResourceLocation.parse("gadomancy:armor_disguise"),data->new DisguiseRecipePage(data.has("invisible")&&data.get("invisible").getAsBoolean()));
        gadomancymodern.knowledge.KnowledgeBookEntity.CLIENT_EFFECTS=KnowledgeBookRenderer::effects;MenuScreens.register(Gadomancy.CLAW_MENU.get(),InfusionClawScreen::new);MenuScreens.register(Gadomancy.PACKAGER_MENU.get(),PackagerScreen::new);
        thaumcraft.api.client.ResearchPageRenderers.register(net.minecraft.resources.ResourceLocation.parse("gadomancy:remote_jar_recipe"),data->new RemoteJarRecipePage());
        thaumcraft.api.client.ResearchPageRenderers.register(new net.minecraft.resources.ResourceLocation("gadomancy","packager_recipe"),data->new PackagerRecipePage());
        for(var item:java.util.List.of(Gadomancy.PACKAGE.get(),Gadomancy.DISGUISED_PACKAGE.get()))
            net.minecraft.client.renderer.item.ItemProperties.register(item,new net.minecraft.resources.ResourceLocation("gadomancy","essentia_wrapper"),(stack,level,entity,seed)->stack.hasTag()&&stack.getTag().getBoolean("essentia_wrapper")?1:0);
    });}
    @SubscribeEvent public static void colors(net.minecraftforge.client.event.RegisterColorHandlersEvent.Item event){event.register((stack,layer)->0,Gadomancy.DARKNESS_ELEMENT.get());for(var item:Gadomancy.AURA_CORES.values())event.register((stack,layer)->layer==0?((gadomancymodern.item.AuraCoreItem)stack.getItem()).color():0xffffff,item.get());}
    @SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers event){event.registerBlockEntityRenderer(Gadomancy.MANIPULATOR_BE.get(),ManipulatorRenderer::new);event.registerBlockEntityRenderer(Gadomancy.FOCUS_BE.get(),ManipulationFocusRenderer::new);event.registerBlockEntityRenderer(Gadomancy.PILLAR_BE.get(),ManipulatorPillarRenderer::new);event.registerBlockEntityRenderer(Gadomancy.PORTAL_BE.get(),AdditionalPortalRenderer::new);event.registerBlockEntityRenderer(Gadomancy.EXTENDED_NODE_BE.get(),ExtendedNodeRenderer::new);event.registerBlockEntityRenderer(Gadomancy.EXTENDED_JAR_BE.get(),context->new tc4revival.client.NodeJarRenderer(context));event.registerEntityRenderer(Gadomancy.DARKNESS_ENTITY.get(),net.minecraft.client.renderer.entity.ItemEntityRenderer::new);event.registerBlockEntityRenderer(Gadomancy.COMPRESSOR_BE.get(),EssentiaCompressorRenderer::new);event.registerBlockEntityRenderer(Gadomancy.ANCIENT_PEDESTAL_BE.get(),context->new AncientPedestalRenderer(context));event.registerEntityRenderer(Gadomancy.HELD_ESSENCE.get(),net.minecraft.client.renderer.entity.ItemEntityRenderer::new);event.registerBlockEntityRenderer(Gadomancy.PYLON_BE.get(),AuraPylonRenderer::new);event.registerEntityRenderer(Gadomancy.SILVERWOOD_ENTITY.get(),tc4revival.client.GolemRenderer::new);event.registerBlockEntityRenderer(Gadomancy.CLAW_BE.get(),InfusionClawRenderer::new);event.registerBlockEntityRenderer(Gadomancy.REMOTE_JAR_BE.get(),RemoteJarRenderer::new);event.registerBlockEntityRenderer(Gadomancy.KNOWLEDGE_BOOK_BE.get(),KnowledgeBookRenderer::new);event.registerEntityRenderer(Gadomancy.HELD_RESEARCH.get(),net.minecraft.client.renderer.entity.ItemEntityRenderer::new);event.registerBlockEntityRenderer(Gadomancy.PACKAGER_BE.get(),PackagerRenderer::new);event.registerBlockEntityRenderer(Gadomancy.DROPPER_BE.get(),DropperRenderer::new);event.registerBlockEntityRenderer(Gadomancy.STICKY_BE.get(),StickyJarRenderer::new);event.registerBlockEntityRenderer(Gadomancy.PROTECTOR_BE.get(),BlockProtectorRenderer::new);event.registerEntityRenderer(Gadomancy.AURA_ENTITY.get(),net.minecraft.client.renderer.entity.ItemEntityRenderer::new);}
}
